let libraryData=null;
function libraryError(error){$('#workspace-error').textContent=error?.message||'';}
async function workspaceTask(task){libraryError(null);try{await task();}catch(e){libraryError(e);toast(e.message);}}
async function loadLibrary(){if(!localRuntime||!csrf)return;try{libraryData=await localRequest('/api/library').then(r=>r.json());renderLibrary();}catch(e){libraryError(e);}}
function fillSelect(id,entries,placeholder){const el=$('#'+id),value=el.value;el.replaceChildren(new Option(placeholder,''),...entries.filter(e=>e.confirmed).map(e=>new Option(e.name,e.id)));if([...el.options].some(o=>o.value===value))el.value=value;}
function renderLibrary(){if(!libraryData)return;fillSelect('template-select',libraryData.templates,'Standardlayout');fillSelect('profile-select',libraryData.profiles,'Standardprofil');fillSelect('example-template',libraryData.templates,'Keine');$('#retention-days').value=libraryData.settings.retentionDays;$('#storage-info').textContent=`${libraryData.storage}. Auftragsfrist: ${libraryData.settings.retentionDays} Tage.`;
 const rows=[];for(const [kind,label]of [['templates','Vorlage'],['profiles','Profil'],['glossary','Begriff'],['examples','Beispiel']])for(const e of libraryData[kind]){const row=document.createElement('div');row.className='library-item';const copy=document.createElement('div'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=kind==='glossary'?e.source+' → '+e.target:e.name;sub.textContent=label+' · '+(e.documentType||e.targetLanguage||'Privat')+(e.scope==='job'?' · nur ein Auftrag':'');copy.append(title,sub);const actions=document.createElement('div');if(['templates','profiles'].includes(kind)){const edit=document.createElement('button');edit.className='text-button';edit.textContent='Bearbeiten';edit.onclick=()=>populateLayout(e,kind);actions.append(edit);}if(kind==='glossary'&&e.scope!=='job'){const edit=document.createElement('button');edit.textContent='Bearbeiten';edit.className='text-button';edit.onclick=()=>{for(const [key,val]of Object.entries({id:e.id,source:e.source,target:e.target,language:e.targetLanguage,note:e.note}))$('#glossary-'+key).value=val;$('#glossary-source').focus();};actions.append(edit);}const remove=document.createElement('button');remove.className='text-button';remove.textContent='Löschen';remove.onclick=()=>{if(confirm('Diesen privaten Eintrag dauerhaft löschen?'))void workspaceTask(async()=>{libraryData=await localRequest('/api/library/remove',{kind,id:e.id}).then(r=>r.json());renderLibrary();});};actions.append(remove);row.append(copy,actions);rows.push(row);}if(!rows.length){const p=document.createElement('p');p.className='muted';p.textContent='Noch keine Einträge. Importiere eine Vorlage oder lege dein erstes Glossarwort an.';rows.push(p);}$('#library-list').replaceChildren(...rows);
}
function populateLayout(e={},kind='templates'){const l=e.layout||{font:'Times New Roman',fontSize:11,lineHeight:1.45,margin:25,titleAlign:'center',pageNumbers:true,includeOriginals:true};for(const[k,v]of Object.entries({id:e.id||'',kind,name:e.name||'',type:e.documentType||'',font:l.font,size:l.fontSize,line:l.lineHeight,margin:l.margin,align:l.titleAlign,fields:(e.fields||[]).join('\n'),header:l.header||'',footer:l.footer||'',certification:l.certification||''}))$('#layout-'+k).value=v;$('#layout-form-fields').value=(e.formFields||[]).map(f=>[f.label,f.sourceLabel,f.kind,f.required?'ja':'nein',f.fileIndex||0,f.page||1,f.box?.join(',')||''].join(' | ')).join('\n');$('#layout-table-width').value=l.tableLabelWidth??38;$('#layout-paragraph').value=l.paragraphSpacing??4.5;$('#layout-keep-rows').checked=l.keepRows!==false;$('#layout-pages').checked=l.pageNumbers;$('#layout-originals').checked=l.includeOriginals;$('#layout-confirmed').checked=e.confirmed===true;$('#layout-form').scrollIntoView({block:'start',behavior:'smooth'});}
async function inspectWordFile(file){if(!file)throw new Error('Bitte eine Word-Datei auswählen.');return localRequest('/api/library/import-word',{file:{name:file.name,type:file.type,data:await fileBase64(file)}}).then(r=>r.json());}
$('#template-file').onchange=()=>void workspaceTask(async()=>{const file=$('#template-file').files[0],suggestion=await inspectWordFile(file);populateLayout({...suggestion,name:file.name.replace(/\.docx$/i,'')});$('#template-import-note').textContent=suggestion.notes.join(' ');});
$('#example-word').onchange=()=>void workspaceTask(async()=>{const suggestion=await inspectWordFile($('#example-word').files[0]);$('#example-text').value=suggestion.text;});
$('#layout-form').onsubmit=e=>{e.preventDefault();void workspaceTask(async()=>{const layout=readLayoutControls();libraryData=await localRequest('/api/library/save',{kind:$('#layout-kind').value,entry:{id:$('#layout-id').value||undefined,name:$('#layout-name').value,documentType:$('#layout-type').value,fields:$('#layout-fields').value.split('\n').filter(Boolean),formFields:readFormDefinitions(),layout,confirmed:$('#layout-confirmed').checked}}).then(r=>r.json());renderLibrary();toast('Bestätigte Vorlage gespeichert.');});};
$('#layout-reset').onclick=()=>{populateLayout();$('#template-file').value='';$('#template-import-note').textContent='';};
$('#glossary-form').onsubmit=e=>{e.preventDefault();void workspaceTask(async()=>{const source=$('#glossary-source').value;libraryData=await localRequest('/api/library/save',{kind:'glossary',entry:{id:$('#glossary-id').value||undefined,name:source,source,target:$('#glossary-target').value,targetLanguage:$('#glossary-language').value,note:$('#glossary-note').value,scope:'global'}}).then(r=>r.json());$('#glossary-form').reset();$('#glossary-id').value='';renderLibrary();toast('Glossar gespeichert.');});};
$('#example-form').onsubmit=e=>{e.preventDefault();void workspaceTask(async()=>{libraryData=await localRequest('/api/library/save',{kind:'examples',entry:{name:$('#example-name').value,documentType:$('#example-type').value,templateId:$('#example-template').value,targetLanguage:$('#example-language').value,sourceText:$('#example-source').value,translation:$('#example-text').value,approved:$('#example-approved').checked,originals:await documentsForRequest([...$('#example-originals').files])}}).then(r=>r.json());$('#example-form').reset();renderLibrary();toast('Privates Beispiel gespeichert.');});};
$('#library-refresh').onclick=()=>void loadLibrary();
$('#retention-form').onsubmit=e=>{e.preventDefault();void workspaceTask(async()=>{if(!confirm('Die neue Frist kann ältere Aufträge sofort löschen. Speichern?'))return;libraryData=await localRequest('/api/settings',{retentionDays:Number($('#retention-days').value)}).then(r=>r.json());renderLibrary();await pollQueue();toast('Löschfrist gespeichert.');});};
$('#backup-download').onclick=()=>void workspaceTask(async()=>{const response=await localRequest('/api/backup',{passphrase:$('#backup-passphrase').value});downloadBlob(await response.blob(),'translateocr-backup.enc');$('#backup-passphrase').value='';toast('Verschlüsseltes Backup erstellt. Passwort sicher aufbewahren.');});
$('#backup-restore').onclick=()=>void workspaceTask(async()=>{const file=$('#backup-file').files[0];if(!file)throw new Error('Bitte ein Backup auswählen.');if(!confirm('Das Backup ersetzt die aktuellen privaten Sammlungen und Aufträge. Vorher eine Sicherung herunterladen. Fortfahren?'))return;await localRequest('/api/backup/restore',{data:await fileBase64(file),passphrase:$('#backup-passphrase').value,confirm:true});location.reload();});
$('#demo-workflow').onclick=()=>void workspaceTask(async()=>{if(!localRuntime)throw new Error('Bitte die lokale Anwendung öffnen.');const {id}=await localRequest('/api/demo',{}).then(r=>r.json());toast('Fiktive Demo gestartet. Es werden keine Dateien an einen Modellanbieter gesendet.');await pollQueue();for(let i=0;i<30;i++){const state=await localRequest('/api/jobs').then(r=>r.json()),job=state.jobs.find(j=>j.id===id);if(job?.hasResult){await openReviewWorkspace(id);return;}if(job?.status==='failed')throw new Error(job.error);await new Promise(r=>setTimeout(r,500));}});
if(localRuntime)void loadLibrary();

$('#layout-preview-button').onclick=()=>void workspaceTask(async()=>{const layout=readLayoutControls();$('#layout-preview-canvas').textContent='Fiktive Vorschau wird aufgebaut …';const response=await localRequest('/api/library/preview',{layout,certification:true}),data=await fileBase64(await response.blob());const {canvas}=await sourceCanvas({type:'application/pdf',data});canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Fiktive PDF-Layoutvorschau');$('#layout-preview-canvas').replaceChildren(canvas);$('#layout-preview-canvas').scrollIntoView({block:'start',behavior:'smooth'});});

function readFormDefinitions(){return $('#layout-form-fields').value.split('\n').filter(l=>l.trim()).map(line=>{const [label,sourceLabel,kind,required,fileIndex,page,box]=line.split('|').map(s=>s.trim());return {label,sourceLabel:sourceLabel||label,kind:kind||'other',required:required!=='nein',fileIndex:Number(fileIndex||0),page:Number(page||1),box:box?box.split(',').map(Number):null};});}
